-- Durable CopilotKit AgentRunner storage. Mastra continues to own model memory;
-- these append-only rows own protocol event replay and cross-instance run state.
CREATE SCHEMA IF NOT EXISTS "mastra";

CREATE TABLE IF NOT EXISTS "mastra"."ag_ui_runs" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "thread_id" text NOT NULL,
  "run_id" text NOT NULL,
  "parent_run_id" text,
  "agent_id" text NOT NULL,
  "status" text NOT NULL,
  "owner_token" uuid NOT NULL,
  "stop_requested" boolean NOT NULL DEFAULT false,
  "lease_expires_at" timestamp with time zone NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "completed_at" timestamp with time zone,
  CONSTRAINT "ag_ui_runs_thread_run_unique" UNIQUE ("thread_id", "run_id"),
  CONSTRAINT "ag_ui_runs_status_check" CHECK (
    "status" IN (
      'running',
      'finalizing',
      'completed',
      'failed',
      'stopped',
      'interrupted'
    )
  )
);

CREATE UNIQUE INDEX IF NOT EXISTS "ag_ui_runs_one_active_thread_idx"
  ON "mastra"."ag_ui_runs" ("thread_id")
  WHERE "status" IN ('running', 'finalizing');

CREATE INDEX IF NOT EXISTS "ag_ui_runs_thread_history_idx"
  ON "mastra"."ag_ui_runs" ("thread_id", "id");

CREATE TABLE IF NOT EXISTS "mastra"."ag_ui_events" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "run_id" bigint NOT NULL REFERENCES "mastra"."ag_ui_runs" ("id") ON DELETE CASCADE,
  "sequence" integer NOT NULL,
  "event" jsonb NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "ag_ui_events_run_sequence_unique" UNIQUE ("run_id", "sequence"),
  CONSTRAINT "ag_ui_events_sequence_check" CHECK ("sequence" >= 0),
  CONSTRAINT "ag_ui_events_object_check" CHECK (jsonb_typeof("event") = 'object')
);
